p::first-letter {
  font-family: "Playfair Display", serif; /* Or a bolder variant of your body font */
  font-weight: 700;
  initial-letter: 3 3; /* Sinks 3 lines, spans 3 lines */
  color: #333;
  margin-right: 0.1em;
  line-height: 1; /* Essential for precise vertical alignment */
  float: left; /* Necessary for initial-letter to function correctly */
  padding-top: 0.1em; /* Fine-tune vertical position */
  /* Add 'text-shadow' for a subtle lift or 'border' for a boxed effect */
}
